/**
 * Live, still-open issues of live projects whose due date has passed. Drives
 * the overdue job; an archived project freezes its issues, so they are never
 * announced.
 */
export async function listOverdueIssues(
  orgId: OrgId,
  now: IsoTimestamp,
): Promise<readonly Issue[]> {
  const archivedProjectIds = getDb()
    .select({ id: projects.id })
    .from(projects)
    .where(
      and(
        orgPredicate(projects.orgId, orgId),
        isNotNull(projects.archivedAt),
      ),
    );

  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          livePredicate(issues.archivedAt, {}),
          notInArray(issues.projectId, archivedProjectIds),
          isNotNull(issues.dueAt),
          lt(issues.dueAt, now),
          inArray(issues.status, ["backlog", "todo", "in_progress", "in_review"]),
        ),
      ),
    )

