import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
import { subscribe } from "@/lib/event-bus";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { resetOverdueTracking, runOverdueIssueJob } from "@/server/jobs/overdue-issue-job";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as issueService from "@/server/services/issue-service";
import * as commentService from "@/server/services/comment-service";
import * as attachmentService from "@/server/services/attachment-service";
import * as projectService from "@/server/services/project-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); resetOverdueTracking(); });
afterAll(() => cleanup());

describe("freeze scratch", () => {
  it("freezes writes while archived, lifts on restore, overdue excludes", async () => {
    const t = await createTenant("freezescratch");
    await usageRepo.recomputeUsage(t.org.id);
    const a = t.actors.admin;
    const m = t.actors.member;
    const issue = await issueService.createIssue(m, issueInput(t.org.id, t.project.id, { title: "Frozen one", dueAt: "2026-01-01T00:00:00.000Z" }));
    const comment = await commentService.createComment(m, { orgId: t.org.id, issueId: issue.id, body: "hi", mentionedUserIds: [] } as any);

    await projectService.archiveProject(a, { orgId: t.org.id, projectId: t.project.id, archiveIssues: false } as any);

    // reads still work
    await expect(issueService.getIssue(m, t.org.id, issue.id)).resolves.toBeTruthy();
    await expect(commentService.getThread(m, t.org.id, issue.id)).resolves.toBeTruthy();

    const seen: string[] = [];
    const off = subscribe("issue.overdue", (p) => { seen.push(p.issueId); });
    await runOverdueIssueJob(new Date("2026-06-01T00:00:00.000Z"));
    off();
    expect(seen).not.toContain(issue.id);

    const before = await issueRepo.findIssueById(t.org.id, issue.id);
    await expect(issueService.updateIssue(m, { orgId: t.org.id, issueId: issue.id, title: "Changed title" } as any)).rejects.toBeInstanceOf(AlreadyArchivedError);
    await expect(issueService.changeIssueStatus(m, { orgId: t.org.id, issueId: issue.id, status: "done" } as any)).rejects.toBeInstanceOf(AlreadyArchivedError);
    await expect(issueService.assignIssue(m, { orgId: t.org.id, issueId: issue.id, assigneeId: null } as any)).rejects.toBeInstanceOf(AlreadyArchivedError);
    await expect(issueService.archiveIssue(m, t.org.id, issue.id)).rejects.toBeInstanceOf(AlreadyArchivedError);
    await expect(commentService.createComment(m, { orgId: t.org.id, issueId: issue.id, body: "x", mentionedUserIds: [] } as any)).rejects.toBeInstanceOf(AlreadyArchivedError);
    await expect(commentService.updateComment(m, { orgId: t.org.id, commentId: comment.id, body: "edit" } as any)).rejects.toBeInstanceOf(AlreadyArchivedError);
    await expect(commentService.deleteComment(m, { orgId: t.org.id, commentId: comment.id } as any)).rejects.toBeInstanceOf(AlreadyArchivedError);
    const after = await issueRepo.findIssueById(t.org.id, issue.id);
    expect(after).toEqual(before);
    expect((await commentRepo.findCommentById(t.org.id, comment.id))?.archivedAt).toBeNull();

    // permission error still precedes the freeze
    await expect(issueService.updateIssue(t.actors.viewer, { orgId: t.org.id, issueId: issue.id, title: "Nope" } as any)).rejects.toThrow();
    await expect(issueService.updateIssue(t.actors.viewer, { orgId: t.org.id, issueId: issue.id, title: "Nope" } as any)).rejects.not.toBeInstanceOf(AlreadyArchivedError);

    await projectService.restoreProject(a, t.org.id, t.project.id);
    const edited = await issueService.updateIssue(m, { orgId: t.org.id, issueId: issue.id, title: "Changed title" } as any);
    expect(edited.title).toBe("Changed title");
    await commentService.createComment(m, { orgId: t.org.id, issueId: issue.id, body: "back", mentionedUserIds: [] } as any);
    const seen2: string[] = [];
    const off2 = subscribe("issue.overdue", (p) => { seen2.push(p.issueId); });
    await runOverdueIssueJob(new Date("2026-06-01T00:00:00.000Z"));
    off2();
    expect(seen2).toContain(issue.id);
  });
});
EOF
